overview.exampleCode:
{partes.map((parte, index) => (
  <TransactionListChildAction
    key={parte.id}
    icon={<Placeholder size={16} />}
    title={parte.titulo}
    description={parte.descricao}
    amount={parte.valor}
    position={
      partes.length === 1
        ? 'standalone'
        : index === 0
        ? 'first'
        : index === partes.length - 1
        ? 'last'
        : 'middle'
    }
    onClick={() => abrirDetalhe(parte.id)}
  />
))}

